import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

import {
  assertNoMissing,
  collectNotices,
  NOTICES_FILE_NAME,
  packageDirOfModule,
  productionClosure,
  renderNotices,
  resolvePackageDir,
} from "./lib.mjs";

// The service worker generated by vite-plugin-pwa inlines these Workbox
// packages (and what they depend on) into dist/workbox-*.js. They are not
// modules of the Vite bundle, so they are named here; closeBundle checks the
// list against the built file.
const SERVICE_WORKER_PACKAGES = ["workbox-core", "workbox-expiration", "workbox-precaching", "workbox-routing", "workbox-strategies"];

// Native Android code compiled into the APK from an npm package that the web
// bundle does not import.
const ANDROID_NATIVE_PACKAGES = { "@capacitor/android": "Android app only (native library)" };

function serviceWorkerDirs(projectDir) {
  const build = resolvePackageDir(projectDir, "workbox-build");
  if (build === null) throw new Error("workbox-build is not installed; cannot find the service worker's packages");
  const dirs = [];
  for (const name of SERVICE_WORKER_PACKAGES) {
    const dir = resolvePackageDir(build, name);
    if (dir === null) throw new Error(`${name} not found from workbox-build`);
    dirs.push(dir, ...productionClosure(dir));
  }
  return dirs;
}

/** Emits THIRD_PARTY_NOTICES.txt for the packages the web build actually contains. */
export function thirdPartyNotices(projectDir) {
  let included = new Set();
  return {
    name: "quki-third-party-notices",
    generateBundle(_options, bundle) {
      const dirs = new Set();
      for (const item of Object.values(bundle)) {
        if (item.type !== "chunk") continue;
        for (const id of Object.keys(item.modules)) {
          const dir = packageDirOfModule(id);
          if (dir !== null) dirs.add(dir);
        }
      }
      for (const dir of serviceWorkerDirs(projectDir)) dirs.add(dir);
      const notes = {};
      for (const [name, note] of Object.entries(ANDROID_NATIVE_PACKAGES)) {
        const dir = resolvePackageDir(projectDir, name);
        if (dir === null) throw new Error(`${name} is not installed`);
        dirs.add(dir);
        notes[name] = note;
      }
      const notices = collectNotices([...dirs], notes);
      assertNoMissing(notices.missing);
      included = new Set(notices.packages.map((p) => p.name));
      this.emitFile({
        type: "asset",
        fileName: NOTICES_FILE_NAME,
        source: renderNotices(notices, "QuKi Notes - third-party notices (web app, Android app, desktop app)"),
      });
    },
    closeBundle: {
      order: "post",
      handler() {
        const outDir = join(projectDir, "dist");
        const tags = new Set();
        for (const f of readdirSync(outDir)) {
          if (!/^workbox-.*\.js$/.test(f)) continue;
          for (const m of readFileSync(join(outDir, f), "utf-8").matchAll(/workbox:([a-z-]+):[0-9.]+/g)) tags.add(`workbox-${m[1]}`);
        }
        const unlisted = [...tags].filter((t) => !included.has(t));
        if (unlisted.length > 0) throw new Error(`The service worker contains ${unlisted.join(", ")}, which have no notice; update SERVICE_WORKER_PACKAGES`);
      },
    },
  };
}
